'use strict';
const CaseUX=(()=>{
 const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const B=(t,a,attrs='',primary=false)=>{const cls=attrs.match(/class="([^"]*)"/)?.[1]||'';return `<button type="button" class="${primary?'primary ':''}${cls}" data-act="ci-ux-${a}" ${attrs.replace(/class="[^"]*"/,'')}>${t}</button>`;};
 const O=(rows,value)=>rows.map(([k,l])=>`<option value="${E(k)}" ${String(k)===String(value)?'selected':''}>${E(l)}</option>`).join('');
 const F=(label,control,help='')=>`<label class="field">${label}${control}${help?`<small>${help}</small>`:''}</label>`;
 const table=(h,rows)=>`<div class="table-scroll ux-table"><table><thead><tr>${h.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
 const badge=(s,type='neutral')=>`<span class="ux-badge ${type}">${E(s)}</span>`;
 const extra=[['interaction','interaction_stop','交互停止条件'],['state','initial_state','初始状态'],['state','state_observation','状态观测方式'],['constraints','forbidden_effects','禁止结果'],['constraints','cleanup','结束后的恢复']];
 function init(w){w.workspace||='home';w.selected||=[];w.activeCase??=0;w.autoStep??=0;w.new_values||={};w.extra_values||={};return w;}
 function stats(w){return {total:w.cases.length,bound:w.cases.filter(c=>c.binding).length,unique:(w.matches||[]).filter((m,i)=>m.status==='unique'&&!w.cases[i].binding&&!w.cases[i].keep_manual).length,pending:w.cases.filter(c=>!c.binding).length};}
 function hasWork(w){return w.started&&!w.completed&&(w.cases.length||w.matrix?.length||w.text?.trim()||w.codeSource?.trim()||Object.values(w.new_values||{}).some(x=>String(x).trim()));}
 function entryLabel(e){const param=e.parameter_label||e.selector?.match(/\[([^\]]+)\]$/)?.[1];return e.title+(param?' · '+({portrait:'纵向版式',landscape:'横向版式'}[param]||param):'');}
 function progress(labels,current){return `<ol class="ux-progress">${labels.map((l,i)=>`<li class="${i===current?'active':i<current?'done':''}"><span>${i<current?'✓':i+1}</span>${l}</li>`).join('')}</ol>`;}
 const footer=(left,right)=>`<div class="ux-footer"><div>${left}</div><div>${right}</div></div>`;
 function home(st,w){const drafts=st.catalog_drafts.filter(d=>d.catalog_key==='case'),published=st.assets.filter(a=>a.kind==='case'),items=[...drafts,...published];const all=items.filter(a=>!w.search||a.name.includes(w.search)||a.spec.source_case_id?.includes(w.search)).filter(a=>!w.filter||(w.filter==='draft'?a.status==='draft':w.filter==='bound'?!!a.spec.automation?.selector:!a.spec.automation?.selector));return `<div class="ux-page-heading"><div><div class="crumb">资产中心 / 场景与用例</div><h2>用例</h2><p>维护验证目标和预期结果，按需要关联自动化。</p></div><div class="actions">${B('导入表格','start-table')}${B('＋ 新建用例','start-new','',true)}</div></div><div class="ux-stat-row"><div><strong>${items.length}</strong><span>全部用例</span></div><div><strong>${drafts.length}</strong><span>草稿</span></div><div><strong>${items.filter(a=>a.spec.automation?.selector).length}</strong><span>已关联自动化</span></div><div><strong>${published.length}</strong><span>已发布</span></div></div>${w.started&&!w.completed?`<div class="ux-info">有一份尚未完成的${w.step===3?'自动化关联':'用例录入'}，内容已暂存。${B('继续处理','resume')}${w.pendingStart?B('放弃当前进度并继续','discard-start'):''}</div>`:''}<div class="ux-list-tools">${F('搜索用例',`<input id="ux-search" value="${E(w.search||'')}" placeholder="用例名称或来源编号">`)}${F('筛选',`<select id="ux-filter">${O([['','全部'],['draft','草稿'],['bound','已关联自动化'],['manual','未关联自动化']],w.filter||'')}</select>`)}<div class="spacer"></div>${B('从自动化程序发现','start-code')}</div>${w.selected.length?`<div class="ux-selection">已选择 ${w.selected.length} 条草稿${B('批量关联自动化','selected-auto','',true)}${B('取消选择','clear-selection')}</div>`:''}${table(['选择','用例名称','内容状态','执行准备','最近操作'],all.map(a=>{const draft=a.status==='draft';return [`<input type="checkbox" data-ux-select="${E(a.id)}" aria-label="选择${E(a.name)}" ${w.selected.includes(a.id)?'checked':''} ${draft?'':'disabled'}>`,`<strong>${E(a.name)}</strong><small>${E(a.spec.source_case_id||'平台新建')} · ${E(a.source?.split(' / ')[0]||'')}</small>`,badge(draft?'草稿':'已发布',draft?'amber':'green'),badge(a.spec.automation?.selector?(a.spec.automation.trial_status==='PASSED'?'已关联 · 已试跑':'已关联 · 待试跑'):a.spec.execution_mode==='platform'?'沿用执行配置':'人工执行'),B(draft?'继续编辑':'查看并新建修订','open',`data-id="${E(a.version_id||a.id)}"`)+(draft?B('关联自动化','open-auto',`data-id="${E(a.id)}"`):'')];}))}${!all.length?'<div class="ux-empty">还没有符合条件的用例。可以新建一条，或从现有表格导入。</div>':''}<div class="ux-hint-card"><strong>只评测模型回答或识别结果？</strong><span>直接使用数据集、指标和评分器即可。</span><button data-act="quick-data">准备评测数据 →</button></div>`;}
 function source(st,w){
  if(w.tab==='code')return `<div class="ux-card"><h3>从自动化代码导入</h3>${programSelect(st,w)}
  ${F('上传 Python 源码或 JSON 入口清单','<input type="file" id="ci-code-file" accept=".py,.json">')}
  ${F('文件名或代码库内路径',`<input id="ci-code-path" value="${E(w.codeFile||'')}" placeholder="tests/test_voltage.py">`)}
  ${F('源码或入口清单',`<textarea id="ci-code-source" rows="6" placeholder="也可以把源码或 JSON 粘贴到这里">${E(w.codeSource||'')}</textarea>`,'可识别顶层无参 pytest 函数。参数化或其他框架使用 JSON 入口清单。')}
  <details><summary>入口清单格式</summary><p>每条填写入口 selector，可选填显示名称 title、参数 parameters 和业务用例编号 case_refs。</p><pre>[{"selector":"tests/test_voltage.py::test_voltage[office]","title":"核对电压","parameters":[{"key":"question","required":true}]}]</pre></details>
  ${B('使用 Office 示例','discover')}</div>${footer(B('返回用例列表','home'),B('识别测试入口','discover-source','',true))}`;
 if(w.tab==='new')return `<div class="ux-card"><h3>填写用例内容</h3><p>先保存业务内容；预期结果或对应的评价方式可在发布前补齐。</p><div class="form-grid">${['用例名称 *','前置条件','操作步骤','预期结果','测试输入'].map((l,i)=>F(l,`<textarea id="ci-new-${i}" rows="${i===2||i===3?4:2}" placeholder="${['例如：拒绝推荐后不执行车控','执行前需要具备的状态或材料','按实际操作顺序填写','具体应看到什么结果','本例的问题、参数或文件说明'][i]}">${E(w.new_values[i]||'')}</textarea>`)).join('')}</div>${elements(w)}${extra.filter(([e])=>w.elements.includes(e)).map(([,k,l])=>F(l,`<textarea id="ci-extra-${k}" rows="2">${E(w.extra_values[k]||'')}</textarea>`)).join('')}</div>${footer(B('返回用例列表','home'),B('下一步：核对内容','single','',true))}`;
 return `<div class="ux-card"><h3>导入已有用例表格</h3><p>使用现有列名，无需先转换为 JSON。支持 Excel、CSV，或直接复制飞书表格。</p><div class="ux-upload"><span class="ux-upload-icon">↑</span><strong>选择用例文件</strong><span>.xlsx / .csv / .tsv</span><label class="file-button">选择文件<input id="ci-file" type="file" accept=".xlsx,.csv,.tsv"></label></div><details ${w.pasteOpen?'open':''}><summary>从飞书表格复制粘贴</summary><p>复制含表头的单元格区域，粘贴到下方。</p><textarea id="ci-source" rows="7" placeholder="在这里粘贴表格内容">${E(w.text||'')}</textarea></details><div class="ux-inline-help">先体验流程：${B('使用 3 条 Office 示例','example')}</div><details><summary>导入来源与适用范围</summary>${F('来源名称',`<input id="ci-namespace" value="${E(w.namespace)}">`,'同一来源重复导入时用于识别原用例。')}${elements(w)}</details></div>${footer(B('返回用例列表','home'),B('下一步：识别表格','parse','',true))}`;
 }
 function elements(w){return `<details class="ux-optional"><summary>按需增加：交互、状态和执行约束</summary>${F('适用对象',`<select id="ci-object-type">${O(CasePolicy.objectTypes,w.object_type)}</select>`)}<div>${CasePolicy.elements.map(([k,l])=>`<label class="metric-choice"><input type="checkbox" data-ci-element="${k}" ${w.elements.includes(k)?'checked':''}>${l}</label>`).join('')}</div><p>只选择本例实际需要检查的内容；已有手工用例可直接保留。</p></details>`;}
 function mapping(w){const head=w.matrix?.[w.header]||[],preview=w.matrix?.[w.header+1]||[];const basic=CaseImport.fields.filter(f=>['source_case_id','title','preconditions','action','expected','input'].includes(f[0])),other=CaseImport.fields.filter(f=>!basic.includes(f));const rows=fs=>fs.map(([k,l])=>[`<strong>${l}${k==='title'?' *':''}</strong>`,`<select aria-label="${l}对应列" data-ci-map="${k}">${O([[-1,'暂不映射'],...head.map((h,i)=>[i,h||'第'+(i+1)+'列'])],w.mapping[k]??-1)}</select>`,E(preview[w.mapping[k]]||'—')]);return `<div class="ux-card"><h3>确认表格识别结果</h3><div class="form-grid">${F('工作表',`<select id="ci-sheet">${O(w.sheets.map((s,i)=>[i,s.name]),w.sheet||0)}</select>`)}${F('表头所在行',`<select id="ci-header">${O(w.matrix.slice(0,12).map((r,i)=>[i,'第 '+(i+1)+' 行']),w.header)}</select>`)}${F('用例排版',`<select id="ci-layout">${O([['row','每行一个用例'],['steps','同一用例占多行步骤']],w.layout)}</select>`)}</div><h4>表格列与用例字段的对应关系</h4><p>已识别的列自动带入，只需调整不正确的对应关系。</p>${table(['用例字段','取自表格哪一列','第一条数据'],rows(basic))}<details><summary>其他字段（标签、约束、已有脚本等）</summary>${table(['用例字段','取自表格哪一列','第一条数据'],rows(other))}</details></div>${footer(B('上一步','back-step'),B('下一步：核对用例','preview','',true))}`;}
 function review(w){const i=Math.min(w.activeCase,w.cases.length-1),c=w.cases[i];if(!c)return `<div class="ux-card"><h3>没有可导入的完整用例</h3>${errors(w)}<p>请检查列对应关系和错误行后重新解析。</p></div>${footer(B('返回上一步','back-step'), '')}`;
 return `<div class="ux-review-head"><div><strong>${w.cases.length} 条用例待保存</strong><span>逐条核对内容；可先保存草稿，再补齐预期或自动化。</span></div>${w.errors.length?badge(w.errors.length+'处导入问题','amber'):badge('表格解析完成','green')}</div>${errors(w)}<div class="ux-master-detail"><div class="ux-case-list">${w.cases.map((c,j)=>B(`<span>${j+1}</span><strong>${E(c.title)}</strong><small>${E(c.source_case_id||'新建用例')}</small>`,'select-case',`data-index="${j}" class="${i===j?'active':''}"`)).join('')}</div><div class="ux-card ux-case-detail"><div class="ux-detail-title"><span>第 ${i+1} / ${w.cases.length} 条</span>${badge(c.binding?'已关联 · 待验证':'人工执行')}${!w.editExisting?B('本次不导入','exclude-case',`data-index="${i}"`):''}</div>${F('用例名称',`<input data-ci-edit="${i}|title" value="${E(c.title)}">`)}<div class="form-grid">${F('验证目标',`<textarea data-ci-edit="${i}|objective" rows="2" placeholder="本例要验证什么">${E(c.objective||'')}</textarea>`)}${F('前置条件',`<textarea data-ci-edit="${i}|preconditions" rows="2">${E(c.preconditions||'')}</textarea>`)}</div>${c.base_spec?.sample_refs?.length?'<div class="ux-info">本例使用已关联的数据集样本。保存时保留原数据引用。</div>':c.base_spec&&Object.keys(c.base_spec.inline_inputs||{}).some(k=>k!=='text')?'<div class="ux-info">本例包含多项输入，已保留原字段及其值。可在资产详情中编辑数据与引用。</div>':F('测试输入',`<textarea data-ci-edit="${i}|input" rows="2">${E(c.input||'')}</textarea>`)}${c.base_spec?.inline_expected&&Object.keys(c.base_spec.inline_expected).some(k=>k!=='steps')?`<div class="ux-info"><strong>本例已有参考内容</strong>${Object.entries(c.base_spec.inline_expected).filter(([k])=>k!=='steps').map(([k,v])=>'<div>'+E(k)+'：'+E(typeof v==='object'?JSON.stringify(v):v)+'</div>').join('')}<small>保留已有参考；下面的逐步预期会一并保存。</small></div>`:''}<div class="ux-section-label">操作与预期结果 ${B('＋ 添加一步','add-step',`data-index="${i}"`)}</div>${(c.steps||[]).map((s,j)=>`<div class="ux-step-row"><span>${j+1}</span><div>${F('操作',`<textarea rows="2" data-ci-step="${i}|${j}|action">${E(s.action)}</textarea>`)}</div><div>${F('预期',`<textarea rows="2" data-ci-step="${i}|${j}|expected">${E(s.expected)}</textarea>`)}</div></div>`).join('')||'<div class="ux-info">已从代码发现测试入口。请添加判断依据，或保存后选择对应指标与评分器。</div>'}<details ${(c.case_elements||[]).length?'open':''}><summary>本例的交互、状态和约束</summary><div>${CasePolicy.elements.map(([k,l])=>`<label class="metric-choice"><input type="checkbox" data-ci-case-element="${i}|${k}" ${(c.case_elements||[]).includes(k)?'checked':''}>${l}</label>`).join('')}</div>${extra.filter(([e])=>(c.case_elements||[]).includes(e)).map(([,k,l])=>F(l,`<textarea data-ci-requirement="${i}|${k}" rows="2">${E(c.requirements?.[k]||'')}</textarea>`)).join('')}</details><div class="ux-detail-foot">${E(c.source_namespace)}${c.source_rows?.length?(c.source_snapshot?.kind==='automation_discovery'?' · 源码第 ':' · 原表第 ')+c.source_rows.join('、')+' 行':''}</div></div></div>${footer(B(w.editExisting?'返回用例列表':'上一步','back-step'),B('保存 '+w.cases.length+' 条用例','save-content','',true))}`;
 }
 function errors(w){return w.errors.length?`<details class="ux-errors"><summary>${w.errors.length} 处问题需要检查，受影响的用例尚未导入</summary>${table(['原表行','原因'],w.errors.map(e=>[e.line,E(e.reason)]))}</details>`:'';}
 function programSelect(st,w){return F('自动化程序',`<select id="ci-program">${O(st.implementations.filter(x=>x.kind==='executor').map(x=>[x.ref,x.name+' · v'+x.version]),w.program||st.implementations.find(x=>x.kind==='executor')?.ref)}</select>`,'选择已登记并固定版本的程序。');}
 function automation(st,w){const s=stats(w);if(w.autoStep===0)return `<div class="ux-card"><h3>为 ${s.total} 条用例选择自动化程序</h3>${programSelect(st,w)}<div class="ux-info">系统会先按已有用例编号匹配，展示结果后由你确认。</div>${table(['本次关联的业务用例','当前执行方式'],w.cases.map(c=>[E(c.title),c.binding?'已有绑定，将保留':'人工执行']))}<details><summary>使用已有的关联表</summary><p>先选择程序；关联表填写“来源用例编号”和“自动化入口”，来源名称可沿用本批设置。</p><input type="file" id="ci-inventory-file" accept=".xlsx,.csv,.tsv"><textarea id="ci-inventory" rows="4" placeholder="粘贴关联表"></textarea>${B('读取关联表','association-table')}</details></div>${footer(B('返回用例列表','home'),B('查看匹配结果','match','',true))}`;
 if(w.autoStep===1)return `<div class="ux-auto-summary">${badge(s.unique+' 条明确匹配','green')}${badge(w.cases.length-s.unique-s.bound+' 条待处理','amber')}${badge(s.bound+' 条保留已有关系')}</div><div class="ux-card"><h3>确认用例与自动化的对应关系</h3><p>明确匹配可一并确认；其他用例可以逐条选择，或保留人工执行。</p>${table(['业务用例','匹配结果','要关联的自动化用例'],w.cases.map((c,i)=>{const m=w.matches?.[i];return [E(c.title)+'<small>'+E(c.source_case_id||'无来源编号')+'</small>',badge(c.binding?'保留已有关系':c.keep_manual?'保持人工执行':m?.status==='unique'?'编号一致':m?.status==='conflict'?'多个候选':m?.status==='suggested'?'仅名称相同':'没有匹配',m?.status==='unique'?'green':'amber'),`<select data-ci-bind="${i}" aria-label="${E(c.title)}的自动化用例">${O([...(c.binding?[['__keep__','保留原关联：'+entryLabel(w.entries.find(e=>e.selector===c.binding.selector&&e.program_version===c.binding.program_version)||{title:'已登记自动化用例',selector:c.binding.selector})]]:[]),...(m?.status==='unique'?[['__recommend__','推荐：'+entryLabel(m.entry)]]:[]),['','保留人工执行，不关联'],...w.entries.filter(e=>e.program_version===w.program).map(e=>[e.selector,entryLabel(e)])],c.binding?'__keep__':c.keep_manual?'':m?.status==='unique'?'__recommend__':'')}</select>`];}))}</div>${footer(B('上一步','auto-back'),B(s.unique?'确认 '+s.unique+' 条明确匹配，下一步':'下一步：核对输入','confirm-matches','',true))}`;
 return `<div class="ux-card"><h3>核对自动化需要的输入</h3><p>已关联 ${s.bound} 条；其余 ${s.total-s.bound} 条保留人工执行。</p>${w.bindingIssues?.length?'<div role="alert" class="ux-alert">'+w.bindingIssues.map(E).join('<br>')+'</div>':''}${w.cases.filter(c=>c.binding).map(c=>{const i=w.cases.indexOf(c),e=w.entries.find(e=>e.selector===c.binding.selector&&e.program_version===c.binding.program_version);return `<div class="ux-param-card"><strong>${E(c.title)}</strong><span> → ${E(e?entryLabel(e):'原有自动化版本')}</span>${(e?.parameters||[]).map(p=>F((p.label||({question:'问题'}[p.key])||p.key)+(p.required?' *':''),`<select data-ci-param="${i}|${E(p.key)}">${O([['','请选择输入来源'],...CaseImport.inputSources(c).map(x=>[x,x==='inputs.text'?'本例测试输入':x.slice(7)])],c.binding.parameter_mapping.find(m=>m.target===p.key)?.source||'')}</select>`)).join('')||'<p>无需额外填写参数，复用已登记配置。</p>'}<details class="technical-only"><summary>程序入口与映射记录</summary><pre>${E(JSON.stringify(c.binding,null,2))}</pre></details></div>`;}).join('')}</div>${footer(B('上一步','auto-back'),B('检查并保存关联','save-auto','',true))}`;
 }
 function complete(w){const s=stats(w);return `<div class="ux-complete"><div class="ux-success-icon">✓</div><h2>${w.completed==='automation'?'自动化关联已保存':'用例已保存'}</h2><p>${E(w.message)}</p><div class="ux-complete-stats"><div><strong>${w.savedCount??s.total}</strong><span>本次保存</span></div><div><strong>${s.bound}</strong><span>已关联 · 待试跑</span></div><div><strong>${s.total-s.bound}</strong><span>人工执行</span></div></div><p>${w.completed==='automation'?'在评测任务中完成试跑，核对实际输出后再正式运行。':'用例内容已保留。需要自动执行时，可继续关联现有程序。'}</p><div class="actions">${B('返回用例列表','home','',true)}${w.completed!=='automation'?B('继续关联自动化','automation'):''}${B('继续核对内容','review')}${w.cases.some(c=>c.draft_id)?B('检查与发布','publish'):''}</div></div>`;}
 function view(st,w){init(w);if(w.workspace==='home')return home(st,w);const auto=w.step===3||w.completed==='automation',labels=auto?['选择程序','确认匹配','核对输入','保存完成']:w.editExisting?['核对用例','保存完成']:w.tab==='new'?['填写内容','核对用例','保存完成']:w.tab==='code'?['选择程序','核对用例','保存完成']:['选择文件','确认列对应','核对用例','保存完成'];const pos=auto?(w.step===4?3:w.autoStep):w.step===4?labels.length-1:w.editExisting?0:w.tab==='table'?w.step:w.step===2?1:0;return `<div class="ux-wizard-heading"><div><div class="crumb">资产中心 / 用例 / ${auto?'关联自动化':w.editExisting?'编辑用例':w.tab==='new'?'新建用例':w.tab==='code'?'从程序发现':'导入表格'}</div><h2>${auto?'关联自动化':w.editExisting?'编辑用例':w.tab==='new'?'新建用例':w.tab==='code'?'从自动化程序发现用例':'导入用例'}</h2></div>${w.step!==4?B('保存进度，稍后继续','home'):''}</div>${progress(labels,pos)}${w.inlineError?`<div class="ux-alert" role="alert">${E(w.inlineError)}</div>`:''}${w.step===4?complete(w):auto?automation(st,w):w.step===2?review(w):w.step===1?mapping(w):source(st,w)}`;}
 function capture(w){for(const [id,key] of [['ci-code-source','codeSource'],['ci-code-path','codeFile']]){const field=document.getElementById(id);if(field)w[key]=field.value;}for(let i=0;i<5;i++){const el=document.getElementById('ci-new-'+i);if(el)w.new_values[i]=el.value;}for(const [,k]of extra){const el=document.getElementById('ci-extra-'+k);if(el)w.extra_values[k]=el.value;}for(const id of ['ci-source','ci-namespace','ci-program']){const el=document.getElementById(id);if(el)w[id==='ci-source'?'text':id==='ci-namespace'?'namespace':'program']=el.value;}for(const el of document.querySelectorAll('[data-ci-edit],[data-ci-step],[data-ci-requirement]'))input(w,el);}
 function input(w,el){if(/^ci-new-[0-4]$/.test(el.id||'')){w.new_values[el.id.slice(-1)]=el.value;}if(el.id==='ci-source')w.text=el.value;if(el.id==='ci-code-source')w.codeSource=el.value;if(el.id==='ci-code-path')w.codeFile=el.value;if(el.id==='ci-namespace')w.namespace=el.value;if((el.id||'').startsWith('ci-extra-'))w.extra_values[el.id.slice(9)]=el.value;if(el.dataset.ciEdit){const [i,k]=el.dataset.ciEdit.split('|');w.cases[i][k]=el.value;if(k==='input'&&w.cases[i].base_spec)w.cases[i].base_spec.inline_inputs={text:el.value};}if(el.dataset.ciStep){const [i,j,k]=el.dataset.ciStep.split('|');w.cases[i].steps[j][k]=el.value;}if(el.dataset.ciRequirement){const [i,k]=el.dataset.ciRequirement.split('|');w.cases[i].requirements||={};w.cases[i].requirements[k]=el.value;}}
 function open(st,ids,auto=false){const rows=ids.map(id=>st.catalog_drafts.find(d=>d.id===id)||st.assets.find(a=>a.version_id===id)).filter(Boolean),cases=[];for(let d of rows){if(d.status==='published'){const previous=st.catalog_drafts.find(x=>x.catalog_key==='case'&&x.id===d.id);d=previous||AssetCatalog.revise(d);if(!previous)st.catalog_drafts.push(d);}CaseWorkbench.openDraft(st,d);cases.push(CaseWorkbench.state(st).cases[0]);}const w=CaseWorkbench.state(st);w.cases=cases;w.workspace='edit';w.started=true;w.editExisting=true;w.step=auto?3:2;w.autoStep=0;w.activeCase=0;w.completed=null;w.bindingIssues=[];w.errors=[];w.matches=null;}
 function action(st,a,b={dataset:{}}){const w=init(CaseWorkbench.state(st));capture(w);w.inlineError='';const core=(name)=>CaseWorkbench.action(st,name,b);if((a==='open'||a==='open-auto'||a==='selected-auto')&&hasWork(w)){w.pendingStart=a;w.pendingArgs={...b.dataset};w.workspace='home';return;}if(a==='home'){w.workspace='home';return;}if(a==='resume'){w.workspace='edit';w.pendingStart=null;return;}if(a==='publish')return 'publish';if(a==='discard-start'){const next=w.pendingStart,args=w.pendingArgs||{};w.started=false;w.pendingStart=null;w.pendingArgs=null;return action(st,next,{dataset:args});}if(a.startsWith('start-')){if(hasWork(w)){w.pendingStart=a;w.pendingArgs={...b.dataset};w.workspace='home';return;}Object.assign(w,{workspace:'edit',started:true,pendingStart:null,namespace:a==='start-new'?'平台新建':'用例表格',tab:a.slice(6),step:0,cases:[],errors:[],matches:null,completed:null,editExisting:false,activeCase:0,autoStep:0,new_values:{},extra_values:{},elements:[],selected:[],text:'',codeSource:'',codeFile:'',matrix:null,sheets:[],sourceName:'',inlineError:'',parsedSignature:null,entries:[],program:st.implementations.find(x=>x.kind==='executor')?.ref});return;}if(a==='open'||a==='open-auto'){open(st,[b.dataset.id],a==='open-auto');return;}if(a==='selected-auto'){if(!w.selected.length)throw Error('先选择需要关联的用例');open(st,w.selected,true);return;}if(a==='clear-selection'){w.selected=[];return;}if(a==='exclude-case'){w.cases.splice(+b.dataset.index,1);w.activeCase=Math.min(w.activeCase,Math.max(0,w.cases.length-1));return;}if(a==='select-case'){w.activeCase=+b.dataset.index;return;}if(a==='add-step'){const c=w.cases[+b.dataset.index];c.steps.push({step_id:'step-'+(c.steps.length+1),action:'',expected:''});return;}if(a==='example'){core('example');w.namespace='Office-PDF';w.pasteOpen=true;return;}if(a==='parse'){core('parse');return;}if(a==='preview'){const signature=JSON.stringify([w.matrix,w.header,w.mapping,w.layout,w.namespace]);if(w.parsedSignature!==signature){core('preview');w.parsedSignature=signature;}else w.step=2;w.activeCase=0;return;}if(a==='single'){core('single');return;}if(a==='discover'){w.namespace='Office-PDF';core('discover');w.step=2;return;}if(a==='discover-source'){w.namespace='自动化程序 · '+w.program;core(a);w.activeCase=0;return;}if(a==='mapping'){w.step=1;return;}if(a==='review'){w.step=2;w.completed=null;return;}if(a==='back-step'){if(!w.cases.length)w.parsedSignature=null;if(w.editExisting){w.workspace='home';return;}w.step=w.step===2?(w.tab==='table'?1:0):0;return;}if(a==='save-content'||a==='save-auto'){if(a==='save-auto'){w.bindingIssues=w.cases.flatMap(c=>CaseImport.validateBindings(c,w.entries.find(e=>e.selector===c.binding?.selector&&e.program_version===c.binding?.program_version)).map(x=>c.title+'：'+x));if(!w.cases.some(c=>c.binding))w.bindingIssues.push('还没有关联自动化用例；可以返回列表保留人工执行。');if(w.bindingIssues.length)return;}core('save');w.savedCount=w.cases.filter(c=>c.draft_id).length;w.completed=a==='save-auto'?'automation':'content';w.step=4;return;}if(a==='automation'){w.step=3;w.autoStep=0;w.completed=null;return;}if(a==='match'){if(!w.entries.length||!w.entries.some(e=>e.program_version===w.program))core('inventory');core('match');w.autoStep=1;return;}if(a==='association-table'){if(!w.entries.some(e=>e.program_version===w.program))core('inventory');core('inventory-paste');core('match');w.autoStep=1;return;}if(a==='confirm-matches'){core('bind-all');w.autoStep=2;return;}if(a==='auto-back'){w.autoStep=Math.max(0,w.autoStep-1);return;}}
 function change(st,el){const w=init(CaseWorkbench.state(st));if(el.dataset.uxSelect){const id=el.dataset.uxSelect;w.selected=el.checked?[...new Set([...w.selected,id])]:w.selected.filter(x=>x!==id);return true;}if(el.id==='ux-filter'){w.filter=el.value;return true;}if(el.id==='ux-search'){w.search=el.value;return true;}return false;}
 return {view,action,change,input,capture,open,init};
})();
